public final class User {
    private final String email;
    private final String name;
    private final List<String> roles;

    // Canonical constructor: the ONLY place that validates.
    public User(String email, String name, List<String> roles) {
        if (email == null || !email.contains("@")) {
            throw new IllegalArgumentException("email required");
        }
        this.email = email;
        this.name = (name == null) ? email : name;
        // Defensive copy: trade allocation for isolation.
        this.roles = List.copyOf(roles == null ? List.of() : roles);
    }

    // Delegating overload: supplies defaults, adds no new checks.
    public User(String email) {
        this(email, null, List.of());
    }

    // Private gate for named creation paths.
    private User(String email, String name) {
        this(email, name, List.of());
    }

    public static User guest() {
        return new User("guest@local", "guest");
    }
}

