class Document {
public:
    // Parameterized: member init list, not assignment in body.
    explicit Document(int size) : size_(size), buf_(new char[size]) {}

    // Copy constructor: deep copy, or two objects own one buffer.
    Document(const Document& other)
        : size_(other.size_), buf_(new char[other.size_]) {
        std::memcpy(buf_, other.buf_, size_);
    }

    Document& operator=(const Document& other) {
        if (this != &other) {
            char* next = new char[other.size_];
            std::memcpy(next, other.buf_, other.size_);
            delete[] buf_;
            buf_ = next;
            size_ = other.size_;
        }
        return *this;
    }

    ~Document() { delete[] buf_; }

private:
    int size_;
    char* buf_;
};
